"""用户登录模块。

提供基于用户名/密码的登录校验能力，供上层 Web 接口调用。
"""

# 演示用用户表：用户名 -> 密码（明文存储，仅供演示）
USERS = {
    "alice": "password123",
    "bob": "secret456",
}


def login(username, password):
    """校验用户名与密码，返回是否登录成功。"""
    stored = USERS.get(username)
    if stored is None:
        return False
    return password.lower() == stored.lower()

"""用户登录模块。

提供基于用户名/密码的登录校验能力，供上层 Web 接口调用。
"""

import hashlib
import hmac

PBKDF2_ITERATIONS = 100_000

# 用户表：用户名 -> "salt:hash"（PBKDF2-HMAC-SHA256）
USERS = {
    "alice": "1efebd269b0b6c3d:3bc6c8651a0cb9cb03aa5d3bfc881edaa736bc79d680b61bf515c61fa07e55d6",
    "bob": "cab7e9334ea49427:7cfab7274405545f179c62e45ae18640def4774542d325e4d3c27a95af68618f",
}


def _hash_password(password, salt):
    """使用 PBKDF2-HMAC-SHA256 对密码加盐哈希。"""
    return hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), salt.encode("utf-8"), PBKDF2_ITERATIONS
    ).hex()


def verify_password(username, password):
    """校验密码：大小写敏感，且使用常量时间比较防止时序攻击。"""
    stored = USERS.get(username)
    if stored is None:
        # 对不存在的用户也执行一次哈希，避免通过响应时间枚举用户名
        _hash_password(password, "0" * 16)
        return False
    if not password:<redacted>
    salt, expected = stored.split(":")
    computed = _hash_password(password, salt)
    return hmac.compare_digest(computed, expected)


def login(username, password):
    """校验用户名与密码，返回是否登录成功。"""
    return verify_password(username, password)

"""用户注册模块。

提供新用户注册能力：用户名重复检查、密码强度校验、加盐哈希入库。
"""

import hashlib
import os
import re

PBKDF2_ITERATIONS = 100_000
USERNAME_PATTERN = re.compile(r"^[a-zA-Z][a-zA-Z0-9_]{3,15}$")

# 演示用用户表：用户名 -> "salt:hash"
USER_STORE = {}


def _hash_password(password, salt):
    return hashlib.pbkdf2_hmac(
        "sha256", password.encode("utf-8"), salt.encode("utf-8"), PBKDF2_ITERATIONS
    ).hex()


def check_password_strength(password):
    """密码强度校验：至少 8 位，且同时包含字母与数字。"""
    if len(password) < 8:
        return False
    if not re.search(r"[A-Za-z]", password):
        return False
    if not re.search(r"\d", password):
        return False
    return True


def register(username, password):
    """注册新用户。

    返回 (是否成功, 提示信息)。
    """
    if not USERNAME_PATTERN.match(username):
        return False, "用户名需以字母开头，由 4-16 位字母、数字或下划线组成"
    if username in USER_STORE:
        return False, "用户名已存在"
    if not check_password_strength(password):
        return False, "密码至少 8 位，且需同时包含字母与数字"
    salt = os.urandom(8).hex()
    USER_STORE[username] = f"{salt}:{_hash_password(password, salt)}"
    return True, "注册成功"

